mapper.select:
SELECT department, `position`, `name`, attendance_date attendanceDate,
       DATE_FORMAT(actual_start_work_time, '%H:%i') actualStartWorkTime,
       DATE_FORMAT(actual_end_work_time, '%H:%i') actualEndWorkTime,
       `type`
FROM attendance_record


        department LIKE concat('%',#{department},'%')


        AND `position` LIKE concat('%',#{position},'%')


        AND `name` LIKE concat('%',#{name},'%')


        AND `type` = #{type}


        AND attendance_date >= #{lessAttendanceDate}


        AND attendance_date <= #{moreAttendanceDate}


        AND (actual_start_work_time IS NULL OR actual_end_work_time IS NULL OR actual_start_work_time > #{fixedStartWorkTime} OR actual_end_work_time < #{fixedEndWorkTime})


        AND name in

            #{name}



ORDER BY attendance_date DESC, person_id

    limit #{page}, #{row}

SELECT COUNT(1) count
FROM attendance_record


        department LIKE concat('%',#{department},'%')


        AND `position` LIKE concat('%',#{position},'%')


        AND `name` LIKE concat('%',#{name},'%')


        AND `type` = #{type}


        AND attendance_date >= #{lessAttendanceDate}


        AND attendance_date <= #{moreAttendanceDate}
